const { chromium } = require('playwright');
const fs = require('fs');
const FINAL_TITLE='Sua vida financeira, em uma tela.';

async function deepest(page){const chain=[];let f=page.mainFrame();for(let i=0;i<12;i++){chain.push(f.url());const kids=f.childFrames();if(!kids.length)break;f=kids[0]}return {f,chain}}
async function waitState(f,predicate,arg,timeout=8000){await f.waitForFunction(predicate,arg,{timeout})}
async function clickNav(f,target){const b=f.locator(`.nav [data-v143-dest="${target}"]`).first();await b.waitFor({state:'visible',timeout:5000});await b.click({timeout:5000});await waitState(f,t=>window.V===t,target,5000);await f.waitForTimeout(120);return await f.evaluate(t=>({target:t,current:window.V,active:Array.from(document.querySelectorAll('.nav button.active')).map(x=>String(x.textContent||'').trim()),text:(document.getElementById('A')?.innerText||document.body.innerText||'').slice(0,5000),updateRoot:!!document.getElementById('v146UpdatesRoot'),renderCount:window.__LTS_V146_UPDATES_RENDER_COUNT||0}),target)}

