  const contentOk=content.marker==='single-render-updates-navigation-v1'&&content.status?.permanent_polling===false&&content.status?.dom_reparenting===false&&content.root&&content.sal.exists&&content.sal.selected==='Restaurantes'&&content.sal.text.includes('99% sugestão')&&content.sal.text.includes('99% identificação')&&content.sal.text.includes('Pesquisa pública')&&!content.sal.safe&&content.gula.selected==='Restaurantes'&&content.gula.text.includes('99% sugestão')&&!content.gula.safe&&content.zig.selected===''&&content.zig.text.includes('Intermediador')&&content.sal.save&&content.sal.newcat;
